-- Comprobación (solo lectura): fechas "premium/VIP/suite" guardadas como normales y ventas de The Rock Orchestra
SELECT a.name AS artista, json_extract(s.snapshot_json, '$.name') AS evento, s.local_date, s.is_package, substr(json_extract(s.snapshot_json, '$.url'), 1, 90) AS url FROM show s LEFT JOIN artist a ON a.id = s.artist_id WHERE s.local_date >= '2026-11-11' AND (lower(json_extract(s.snapshot_json, '$.name')) LIKE '%premium%' OR lower(json_extract(s.snapshot_json, '$.name')) LIKE '%suite%' OR lower(json_extract(s.snapshot_json, '$.url')) LIKE '%premium%' OR lower(json_extract(s.snapshot_json, '$.name')) LIKE '%lounge%' OR lower(json_extract(s.snapshot_json, '$.name')) LIKE '%club seat%') LIMIT 40;
SELECT json_extract(s.snapshot_json, '$.name') AS evento, s.local_date, json_extract(s.snapshot_json, '$.status') AS estado, json_extract(s.snapshot_json, '$.sales') AS ventas, substr(s.updated_at, 6, 11) AS act FROM show s JOIN artist a ON a.id = s.artist_id WHERE a.name = 'The Rock Orchestra';
